    category, title, content, status, submitted_by_id, submitted_by_name,
    submitted_by_username, client_ip, user_agent, device_type, page_url,
    diagnostic_json, created_by, updated_by
) VALUES (
    #{category}, #{title}, #{content}, #{status}, #{submittedById},
