SELECT id
FROM sys_file
WHERE uploader_id = #{userId}
  AND deleted_at = 0
  AND id IN
  
      #{fileId}

SELECT , ( SELECT COUNT(*) FROM sys_feedback_file_binding binding WHERE binding.feedback_id = sys_feedback.id AND binding.deleted_at = 0 ) AS attachment_count FROM sys_feedback WHERE deleted_at = 0 AND category = #{category} AND status = #{status}
AND ( CAST(id AS CHAR) LIKE CONCAT('%', #{keyword}, '%') OR title LIKE CONCAT('%', #{keyword}, '%') OR content LIKE CONCAT('%', #{keyword}, '%') OR submitted_by_name LIKE CONCAT('%', #{keyword}, '%') OR submitted_by_username LIKE CONCAT('%', #{keyword}, '%') OR client_ip LIKE CONCAT('%', #{keyword}, '%') OR owner_name LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY id DESC LIMIT #{offset}, #{pageSize}
